    f_best = func(x_best)

    for i in range(int(2/beta)):
        x_rand = np.random.uniform(lb, ub, size=(n,))
        fx_rand = func(x_rand)

        if fx_rand < f_best:
            f_best = fx_rand
            x_best = x_rand

    learning_rate = 1e-5 / (i + 1)**0.9

    for i in range(int(beta)):
        g = np.zeros(n)
        e = np.zeros(n)

        for j in range(10):
